const values = [
    variables['c6ae3c60-2772-49f6-9403-225a512d2522'],
    variables['a692a962-903e-4fa2-a6b9-0704547a2367'],
    variables['763a3ac0-ee6a-413f-983c-173b66d1c33d'],
    variables['fd179da4-0806-43c1-88e5-448f7de15584'],
    variables['480ddaa3-3d38-49ff-9601-2c784831b065'],
    variables['d4d0b43b-4f66-4a5b-90ae-cf3ef12db72c'],
];

// Преобразуем в числа, фильтруем пустые, 0 и невалидные
const numbers = values
    .map(val => parseFloat(val))
    .filter(num => !isNaN(num) && num > 0); // только > 0

if (numbers.length === 0) return 0;

// Считаем среднее
const sum = numbers.reduce((total, num) => total + num, 0);
const average = sum / numbers.length;

// Округляем до 1 знака после запятой
return Math.round(average * 10) / 10;

