    return new Date(Date.UTC(
        now.getFullYear(),
        now.getMonth(),
        now.getDate(),
        0, 0, 0
    )).toISOString();
}

const months = {
    'января': 0, 'февраля': 1, 'марта': 2, 'апреля': 3,
    'мая': 4, 'июня': 5, 'июля': 6, 'августа': 7,
    'сентября': 8, 'октября': 9, 'ноября': 10, 'декабря': 11
};

// Пробуем разные форматы

// 1. Формат "5 февраля 2026"
const ruMatch = dateStr.match(/^(\d{1,2})\s+([а-яё]+)\s+(\d{4})$/i);
if (ruMatch) {
    const day = parseInt(ruMatch[1]);
    const monthIndex = months[ruMatch[2].toLowerCase()];
    const year = parseInt(ruMatch[3]);

    if (!isNaN(day) && monthIndex !== undefined && !isNaN(year)) {
        return new Date(Date.UTC(year, monthIndex, day, 0, 0, 0)).toISOString();
    }
}

// 2. Формат "2026-02-05" (YYYY-MM-DD)
const isoMatch = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
if (isoMatch) {
    const year = parseInt(isoMatch[1]);
    const month = parseInt(isoMatch[2]) - 1;
    const day = parseInt(isoMatch[3]);

    if (!isNaN(year) && !isNaN(month) && !isNaN(day)) {
        return new Date(Date.UTC(year, month, day, 0, 0, 0)).toISOString();
    }
}

// 3. Пробуем стандартный парсер Date как fallback
const date = new Date(dateStr);
if (!isNaN(date.getTime())) {
    const utcDate = new Date(Date.UTC(
        date.getFullYear(),
        date.getMonth(),
        date.getDate(),
        0, 0, 0
    ));
    return utcDate.toISOString();
}

